-- Лекция 1 (lesson 1960, cmid 13413, курс 238): убрать короткие описания над видео
CREATE TABLE IF NOT EXISTS _kab_bk20260927b_l1960_pages AS SELECT * FROM mdl_lesson_pages WHERE lessonid=1960;
UPDATE mdl_lesson_pages SET contents = REPLACE(contents, CONVERT(X'' USING utf8mb4), ''), timemodified = UNIX_TIMESTAMP() WHERE id=17879 AND lessonid=1960 AND LOCATE(CONVERT(X'' USING utf8mb4), contents) > 0;
UPDATE mdl_lesson_pages SET contents = REPLACE(contents, CONVERT(X'' USING utf8mb4), ''), timemodified = UNIX_TIMESTAMP() WHERE id=17879 AND lessonid=1960 AND LOCATE(CONVERT(X'' USING utf8mb4), contents) > 0;
