UPDATE mdl_lesson_pages SET contents = REPLACE(contents, CONVERT(X'' USING utf8mb4), ''), timemodified = UNIX_TIMESTAMP() WHERE id=17881 AND lessonid=1960 AND LOCATE(CONVERT(X'' USING utf8mb4), contents) > 0;
UPDATE mdl_lesson_pages SET contents = REPLACE(contents, CONVERT(X'' USING utf8mb4), ''), timemodified = UNIX_TIMESTAMP() WHERE id=17881 AND lessonid=1960 AND LOCATE(CONVERT(X'' USING utf8mb4), contents) > 0;
SELECT id, LENGTH(contents) len, MD5(contents) md5, (LENGTH(contents)-LENGTH(REPLACE(contents,'<video','')))/6 n_video FROM mdl_lesson_pages WHERE lessonid=1960 ORDER BY id;
